public class NegativeMarginDetector extends ResourceXmlDetector {
    private static final String ISSUE_ID = "NegativeMargin";
    private static final String DESCRIPTION = "Checks for negative margin values";
    private static final String EXPLANATION = "Margin values should be positive. Negative values ...";

    static final Issue ISSUE = Issue.create(
        ISSUE_ID,
        "Negative Margins",
        EXPLANATION,
        Category.LAYOUT,
        5,
        Severity.WARNING,
        new Implementation(NegativeMarginDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    @Override public Collection<String> getApplicableAttributes() {
        return Arrays.asList(
            SdkConstants.ATTR_LAYOUT_MARGIN,
            SdkConstants.ATTR_LAYOUT_MARGIN_LEFT,
            SdkConstants.ATTR_LAYOUT_MARGIN_RIGHT,
            SdkConstants.ATTR_LAYOUT_MARGIN_TOP,
            SdkConstants.ATTR_LAYOUT_MARGIN_BOTTOM,
            SdkConstants.ATTR_LAYOUT_MARGIN_START,
            SdkConstants.ATTR_LAYOUT_MARGIN_END,
            SdkConstants.ATTR_LAYOUT_MARGIN_HORIZONTAL,
            SdkConstants.ATTR_LAYOUT_MARGIN_VERTICAL
        );
    }

    @Override public void visitAttribute(XmlContext context, Attr attribute) {
        String value = attribute.getValue();
        if (value == null || value.isEmpty()) return;
        if (value.charAt(0) == '-') {
            // ensure it's a dimension, not a negative ID or expression
            if (isDimension(value)) {
                context.report(ISSUE, attribute, context.getValueLocation(attribute),
                    "Margin values should not be negative");
            }
        }
    }

    private static boolean isDimension(String value) {
        // matches optional sign and number and unit
        return value.matches("-?\\d+(\\.\\d+)?(dp|dip|px|pt|in|mm|sp|sIP?)")? Actually units: dp, dip, px, pt, in, mm, sp. Regex.
    }

